"use client"

import { Button as BaseButton } from "@base-ui/react/button"
import type { ComponentProps } from "react"

import {
  buttonVariants,
  type ButtonVariantProps,
} from "@/components/ui/button-variants"
import { cn } from "@/lib/utils"

/**
 * Props for the nk Button built on Base UI.
 */
type ButtonProps = ComponentProps<typeof BaseButton> & ButtonVariantProps

/**
 * Accessible button with nk product styling. Uses Base UI for behavior
 * and gap-based spacing so LTR and RTL both work.
 */
const Button = ({ className, variant, size, ...props }: ButtonProps) => {
  return (
    <BaseButton
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    />
  )
}

export { Button, buttonVariants }
export type { ButtonProps }

import { cva, type VariantProps } from "class-variance-authority"

/**
 * Visual variants for the nk Button component.
 */
const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 rounded-md text-sm font-medium whitespace-nowrap transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/90",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        outline:
          "border border-border bg-background hover:bg-accent hover:text-accent-foreground",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        destructive:
          "bg-destructive text-destructive-foreground hover:bg-destructive/90",
      },
      size: {
        sm: "h-8 px-3 text-xs",
        default: "h-9 px-4 py-2",
        lg: "h-10 px-6",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

type ButtonVariantProps = VariantProps<typeof buttonVariants>

export { buttonVariants }
export type { ButtonVariantProps }
